"""Level 3 (standards) and level 4 (procedures) clause libraries, EN/FR.

Standards hold measurable parameters so that policies stay short and stable; procedures say who does what,
in which order, with which records. Parameters are organization decisions ({p:DEC-…}) or explicit
placeholders; values marked as good practice must be confirmed by the owner.
"""
from .common import C, S, TBL, V, procedure_frame, standard_frame

# ================================================================== STANDARDS
STD_AUTH = standard_frame(
    purpose=[C("P01", "This standard sets the minimum authentication requirements for accounts that access {org}’s information and systems.",
               "La présente norme fixe les exigences minimales d’authentification des comptes qui accèdent à l’information et aux systèmes de {org}.", mod="info")],
    applicability=[C("AP01", "It applies to every user, privileged, service and third-party account on systems owned or used by {org}, including cloud services. Multi-factor authentication is mandatory for: {p:DEC-IAM-MFA-SCOPE}.",
                     "Elle s’applique à tous les comptes d’utilisateurs, privilégiés, de service et de tiers sur les systèmes possédés ou utilisés par {org}, y compris les services infonuagiques. L’authentification multifacteur est obligatoire pour : {p:DEC-IAM-MFA-SCOPE}.",
                     src="decision", inputs=["DEC-IAM-MFA-SCOPE"])],
    requirements=[
        S("SEC-REQ-PWD", "Passwords", "Mots de passe", [
            C("PW01", by="DEC-AUTH-MINLEN", src="decision", variants={
                "15_8": V("Passwords must contain at least 15 characters, or at least 8 characters when multi-factor authentication protects the account. Systems must accept at least 64 characters, spaces and all printable characters.",
                          "Les mots de passe doivent compter au moins 15 caractères, ou au moins 8 caractères lorsque l’authentification multifacteur protège le compte. Les systèmes doivent accepter au moins 64 caractères, les espaces et tous les caractères imprimables."),
                "12": V("Passwords must contain at least 12 characters. Systems must accept at least 64 characters, spaces and all printable characters.",
                        "Les mots de passe doivent compter au moins 12 caractères. Les systèmes doivent accepter au moins 64 caractères, les espaces et tous les caractères imprimables."),
                "14": V("Passwords must contain at least 14 characters. Systems must accept at least 64 characters, spaces and all printable characters.",
                        "Les mots de passe doivent compter au moins 14 caractères. Les systèmes doivent accepter au moins 64 caractères, les espaces et tous les caractères imprimables."),
                "_none": V("Passwords must contain at least [DECISION: minimum password length] characters.",
                           "Les mots de passe doivent compter au moins [DÉCISION : longueur minimale des mots de passe] caractères.")},
              refs=["ISO 27002:2022 5.17", "NIST SP 800-63B"]),
            C("PW02", "New and changed passwords must be checked against a list of commonly used and known-compromised passwords and rejected if they match.",
              "Les mots de passe nouveaux ou modifiés doivent être comparés à une liste de mots de passe courants ou connus comme compromis et refusés s’ils y figurent.", refs=["ISO 27002:2022 5.17"]),
            C("PW03", "Composition rules (mandatory mixes of character types) and periodic forced changes must not be imposed; a password must be changed when there is evidence or suspicion of compromise.",
              "Des règles de composition (mélanges obligatoires de types de caractères) et des changements périodiques forcés ne doivent pas être imposés; un mot de passe doit être changé lorsqu’il y a preuve ou soupçon de compromission.",
              mod="must not", refs=["NIST SP 800-63B"]),
            C("PW04", by="DEC-AUTH-LOCKOUT", src="decision", variants={
                "5": V("After 5 consecutive failed sign-in attempts, the account must be locked for a period or throttled so that guessing is impractical.",
                       "Après 5 tentatives de connexion consécutives échouées, le compte doit être verrouillé pour une période ou ralenti afin de rendre la devinette impraticable."),
                "10": V("After 10 consecutive failed sign-in attempts, the account must be locked for a period or throttled so that guessing is impractical.",
                        "Après 10 tentatives de connexion consécutives échouées, le compte doit être verrouillé pour une période ou ralenti afin de rendre la devinette impraticable."),
                "_none": V("After [DECISION: number of failed attempts] consecutive failed sign-in attempts, the account must be locked or throttled.",
                           "Après [DÉCISION : nombre de tentatives échouées] tentatives de connexion consécutives échouées, le compte doit être verrouillé ou ralenti.")}),
            C("PW05", "A password manager approved by {sec} should be provided to staff who hold several credentials.",
              "Un gestionnaire de mots de passe approuvé par {sec} devrait être fourni au personnel qui détient plusieurs authentifiants.", mod="should"),
        ]),
        S("SEC-REQ-MFA", "Multi-factor authentication", "Authentification multifacteur", [
            C("MF01", by="DEC-AUTH-FACTORS", src="decision", variants={
                "phishing_resistant_admin": V("Accepted second factors are an authenticator application with number matching or a hardware security key. Administrators must use a phishing-resistant method (FIDO2 security key or passkey). SMS and voice codes are accepted only as a temporary recovery method approved by {sec}.",
                                              "Les seconds facteurs acceptés sont une application d’authentification avec correspondance de nombres ou une clé de sécurité matérielle. Les administrateurs doivent utiliser une méthode résistante à l’hameçonnage (clé de sécurité FIDO2 ou clé d’accès). Les codes par SMS ou par appel ne sont acceptés que comme méthode de récupération temporaire approuvée par {sec}."),
                "app_token": V("Accepted second factors are an authenticator application or a hardware token. SMS and voice codes are not accepted.",
                               "Les seconds facteurs acceptés sont une application d’authentification ou un jeton matériel. Les codes par SMS ou par appel ne sont pas acceptés."),
                "any": V("Accepted second factors are an authenticator application, a hardware token or, as a fallback, an SMS code. The residual risk of SMS interception is accepted by [ROLE: risk owner].",
                         "Les seconds facteurs acceptés sont une application d’authentification, un jeton matériel ou, en solution de repli, un code par SMS. Le risque résiduel d’interception des SMS est accepté par [RÔLE : responsable du risque]."),
                "_none": V("Accepted second factors are [DECISION: accepted second factors].", "Les seconds facteurs acceptés sont [DÉCISION : seconds facteurs acceptés].")},
              refs=["ISO 27002:2022 8.5", "NIST CSF 2.0 PR.AA"]),
            C("MF02", "Resetting a second factor requires verifying the person’s identity through a channel other than the one being reset.",
              "La réinitialisation d’un second facteur exige de vérifier l’identité de la personne par un canal différent de celui qui est réinitialisé."),
        ]),
        S("SEC-REQ-SESSION", "Sessions and devices", "Sessions et appareils", [
            C("SE01", by="DEC-AUTH-SCREENLOCK", src="decision", variants={
                "5": V("Workstations and mobile devices must lock automatically after 5 minutes of inactivity.", "Les postes et appareils mobiles doivent se verrouiller automatiquement après 5 minutes d’inactivité."),
                "10": V("Workstations and mobile devices must lock automatically after 10 minutes of inactivity.", "Les postes et appareils mobiles doivent se verrouiller automatiquement après 10 minutes d’inactivité."),
                "15": V("Workstations and mobile devices must lock automatically after 15 minutes of inactivity.", "Les postes et appareils mobiles doivent se verrouiller automatiquement après 15 minutes d’inactivité."),
                "_none": V("Workstations and mobile devices must lock automatically after [DECISION: inactivity delay] of inactivity.",
                           "Les postes et appareils mobiles doivent se verrouiller automatiquement après [DÉCISION : délai d’inactivité] d’inactivité.")},
              refs=["ISO 27002:2022 8.1"]),
            C("SE02", "Remote-access and administrative sessions must end or require re-authentication after [VALUE: maximum session duration in hours].",
              "Les sessions d’accès à distance et d’administration doivent prendre fin ou exiger une nouvelle authentification après [VALEUR : durée maximale de session en heures]."),
        ]),
        S("SEC-REQ-SERVICE", "Service accounts and secrets", "Comptes de service et secrets", [
            C("SV01", "Service-account passwords and API secrets must be randomly generated with at least 32 characters, stored only in an approved secrets vault, and never sent by email or chat.",
              "Les mots de passe des comptes de service et les secrets d’API doivent être générés aléatoirement, compter au moins 32 caractères, être conservés uniquement dans un coffre de secrets approuvé et ne jamais être transmis par courriel ou clavardage.",
              refs=["ISO 27002:2022 5.17"]),
            C("SV02", "Secrets must be changed when a person who knew them leaves or changes role, and when compromise is suspected.",
              "Les secrets doivent être changés lorsqu’une personne qui les connaissait quitte ou change de fonctions, et en cas de soupçon de compromission."),
            C("SV03", "Default and vendor-supplied credentials must be changed before a system or device is connected to the network.",
              "Les authentifiants par défaut ou fournis par le fabricant doivent être changés avant qu’un système ou un appareil soit branché au réseau.", refs=["ISO 27002:2022 8.9", "CIS v8.1 4"]),
        ]),
    ],
    evidence=[C("EV01", "Evidence of compliance includes identity-provider configuration exports, MFA enrolment reports, and lists of exceptions; {sec} reviews them at least annually.",
                "Les preuves de conformité comprennent les exportations de configuration du fournisseur d’identité, les rapports d’inscription à l’AMF et la liste des dérogations; {sec} les examine au moins une fois par année.",
                gap=("TECH-04", ["no", "partial"], V("MFA is not yet deployed everywhere this standard requires it.", "L’AMF n’est pas encore déployée partout où la norme l’exige.")))],
)

STD_HANDLING = standard_frame(
    purpose=[C("P01", "This standard translates each classification level into concrete handling rules so that every person can protect information the same way.",
               "La présente norme traduit chaque niveau de classification en règles de manipulation concrètes afin que chacun protège l’information de la même façon.", mod="info")],
    applicability=[C("AP01", "It applies to information in every form — documents, email, databases, cloud storage, paper and removable media — and to everyone who handles {org} information.",
                     "Elle s’applique à l’information sous toutes ses formes — documents, courriels, bases de données, stockage infonuagique, papier et supports amovibles — et à toute personne qui manipule l’information de {org}.", mod="info")],
    requirements=[
        S("SEC-REQ-MATRIX", "Handling matrix", "Matrice de manipulation", [
            {"id": "HM01", "dynamic": "handling_matrix", "modality": "must", "src": "framework", "refs": ["ISO 27002:2022 5.13", "ISO 27002:2022 5.14"], "inputs": ["DATA-02B"]},
        ]),
        S("SEC-REQ-RULES", "Specific rules", "Règles particulières", [
            C("HR01", by="DEC-HDL-CLOUD", src="decision", variants={
                "approved_list": V("Information classified Confidential or above may be stored only in storage services on the list approved by {sec}; personal cloud accounts must not be used.",
                                   "L’information classifiée Confidentiel ou plus ne peut être stockée que dans les services de stockage figurant sur la liste approuvée par {sec}; les comptes infonuagiques personnels ne doivent pas être utilisés."),
                "tenant": V("Information classified Confidential or above may be stored only in {org}’s own collaboration environment; personal cloud accounts must not be used.",
                            "L’information classifiée Confidentiel ou plus ne peut être stockée que dans l’environnement de collaboration de {org}; les comptes infonuagiques personnels ne doivent pas être utilisés."),
                "_none": V("Information classified Confidential or above may be stored only in [DECISION: approved storage locations].",
                           "L’information classifiée Confidentiel ou plus ne peut être stockée que dans [DÉCISION : emplacements de stockage approuvés].")},
              refs=["ISO 27002:2022 5.23"]),
            C("HR02", by="DEC-HDL-USB", src="decision", variants={
                "encrypted_only": V("Removable media may be used only if issued by {org} and encrypted; information classified {class_top} must not be copied to removable media without the owner’s written approval.",
                                    "Les supports amovibles ne peuvent être utilisés que s’ils sont fournis par {org} et chiffrés; l’information classifiée {class_top} ne doit pas y être copiée sans l’approbation écrite de son responsable."),
                "blocked": V("Removable media are blocked on {org} devices; exceptions require approval through {exc_ref}.",
                             "Les supports amovibles sont bloqués sur les appareils de {org}; les exceptions exigent une approbation selon {exc_ref}."),
                "_none": V("Use of removable media: [DECISION: removable media rule].", "Utilisation des supports amovibles : [DÉCISION : règle sur les supports amovibles].")},
              refs=["ISO 27002:2022 7.10"]),
            C("HR03", "Before sending information classified Confidential or above by email, users must verify the recipients’ addresses; external sending requires encryption or a secure sharing link with expiry.",
              "Avant d’envoyer par courriel de l’information classifiée Confidentiel ou plus, les utilisateurs doivent vérifier les adresses des destinataires; l’envoi externe exige un chiffrement ou un lien de partage sécurisé avec échéance.",
              refs=["ISO 27002:2022 5.14"]),
            C("HR04", "Information entered into artificial intelligence tools must respect the limit set in the artificial intelligence use policy: {p:DEC-AI-DATA}.",
              "L’information saisie dans des outils d’intelligence artificielle doit respecter la limite fixée dans la politique d’utilisation de l’intelligence artificielle : {p:DEC-AI-DATA}.",
              src="decision", inputs=["DEC-AI-DATA"], when=lambda p: p.has("DATA-06", "ai_tools", "ai_products")),
        ]),
    ],
    evidence=[C("EV01", "Evidence includes data-loss-prevention or sharing reports, storage location reviews and disposal certificates for media and paper.",
                "Les preuves comprennent les rapports de prévention des fuites ou de partage, les revues des emplacements de stockage et les certificats d’élimination des supports et du papier.", mod="info")],
)

STD_CRYPTO = standard_frame(
    purpose=[C("P01", "This standard sets the cryptographic protocols, algorithms and key-management practices that {org} systems must use.",
               "La présente norme fixe les protocoles, algorithmes et pratiques de gestion des clés que les systèmes de {org} doivent utiliser.", mod="info")],
    applicability=[C("AP01", "It applies to systems, applications, devices and services that store or transmit {org} information, including those operated by suppliers.",
                     "Elle s’applique aux systèmes, applications, appareils et services qui stockent ou transmettent l’information de {org}, y compris ceux exploités par des fournisseurs.", mod="info")],
    requirements=[
        S("SEC-REQ-TRANSIT", "Data in transit", "Données en transit", [
            C("TR01", by="DEC-CRY-TLS", src="decision", variants={
                "1.2": V("Network connections carrying information classified Internal or above over untrusted networks must use TLS 1.2 or higher; TLS 1.3 should be enabled wherever supported.",
                         "Les connexions transportant de l’information classifiée Interne ou plus sur des réseaux non fiables doivent utiliser TLS 1.2 ou une version ultérieure; TLS 1.3 devrait être activé partout où il est pris en charge."),
                "1.3": V("Network connections carrying information classified Internal or above over untrusted networks must use TLS 1.3.",
                         "Les connexions transportant de l’information classifiée Interne ou plus sur des réseaux non fiables doivent utiliser TLS 1.3."),
                "_none": V("Network connections over untrusted networks must use TLS [DECISION: minimum TLS version] or higher.",
                           "Les connexions sur des réseaux non fiables doivent utiliser TLS [DÉCISION : version minimale de TLS] ou une version ultérieure.")},
              refs=["ISO 27002:2022 8.24", "NIST CSF 2.0 PR.DS"]),
            C("TR02", "SSL, TLS 1.0 and TLS 1.1, and cipher suites without forward secrecy, must be disabled.",
              "SSL, TLS 1.0 et TLS 1.1, ainsi que les suites de chiffrement sans confidentialité persistante, doivent être désactivés.", mod="must"),
        ]),
        S("SEC-REQ-REST", "Data at rest", "Données au repos", [
            C("RS01", "Laptops, mobile devices and removable media must use full-disk or device encryption. Servers, databases, cloud storage and backups holding information classified Confidential or above must be encrypted at rest.",
              "Les ordinateurs portables, appareils mobiles et supports amovibles doivent utiliser le chiffrement complet du disque ou de l’appareil. Les serveurs, bases de données, stockages infonuagiques et sauvegardes contenant de l’information classifiée Confidentiel ou plus doivent être chiffrés au repos.",
              refs=["ISO 27002:2022 8.24"]),
        ]),
        S("SEC-REQ-ALGO", "Approved and prohibited algorithms", "Algorithmes approuvés et interdits", [
            C("AL01", "Approved", "Approuvés", mod="must", table=TBL(
                ["Purpose", "Approved", "Prohibited"], ["Usage", "Approuvés", "Interdits"],
                [["Symmetric encryption", "AES-128 or AES-256 (GCM or another authenticated mode)", "DES, 3DES, RC4, AES-ECB"],
                 ["Asymmetric encryption and signatures", "RSA 3072 bits or more; ECDSA/ECDH on P-256 or stronger; Ed25519", "RSA below 2048 bits, DSA"],
                 ["Hashing", "SHA-256 or stronger; for passwords: Argon2id, scrypt, bcrypt or PBKDF2 with a high work factor", "MD5, SHA-1, unsalted hashes"],
                 ["Protocols", "TLS (version per this standard), SSH 2, IPsec IKEv2", "SSL, TLS 1.0/1.1, SSH 1, Telnet, FTP"]],
                [["Chiffrement symétrique", "AES-128 ou AES-256 (GCM ou autre mode authentifié)", "DES, 3DES, RC4, AES-ECB"],
                 ["Chiffrement asymétrique et signatures", "RSA de 3072 bits ou plus; ECDSA/ECDH sur P-256 ou plus robuste; Ed25519", "RSA de moins de 2048 bits, DSA"],
                 ["Hachage", "SHA-256 ou plus robuste; pour les mots de passe : Argon2id, scrypt, bcrypt ou PBKDF2 avec un facteur de travail élevé", "MD5, SHA-1, hachages sans sel"],
                 ["Protocoles", "TLS (version selon la présente norme), SSH 2, IPsec IKEv2", "SSL, TLS 1.0/1.1, SSH 1, Telnet, FTP"]]),
              refs=["ISO 27002:2022 8.24"]),
            C("AL02", "{org} maintains an inventory of where cryptography is used, to prepare the migration to post-quantum algorithms.",
              "{org} tient un inventaire des endroits où la cryptographie est utilisée afin de préparer la migration vers des algorithmes post-quantiques.", mod="should"),
        ]),
        S("SEC-REQ-KEYS", "Keys and certificates", "Clés et certificats", [
            C("KY01", "Encryption keys must be generated by approved tools, stored in a key-management service or hardware security module where available, and never stored alongside the data they protect.",
              "Les clés de chiffrement doivent être générées par des outils approuvés, conservées dans un service de gestion des clés ou un module matériel de sécurité lorsqu’il en existe un, et jamais à côté des données qu’elles protègent.",
              refs=["ISO 27002:2022 8.24"]),
            C("KY02", by="DEC-CRY-KEYROT", src="decision", variants={
                "annual": V("Keys managed by {org} must be rotated at least annually and immediately on suspected compromise.", "Les clés gérées par {org} doivent être renouvelées au moins une fois par année et immédiatement en cas de compromission soupçonnée."),
                "biennial": V("Keys managed by {org} must be rotated at least every two years and immediately on suspected compromise.", "Les clés gérées par {org} doivent être renouvelées au moins tous les deux ans et immédiatement en cas de compromission soupçonnée."),
                "_none": V("Keys managed by {org} must be rotated [DECISION: key rotation period].", "Les clés gérées par {org} doivent être renouvelées [DÉCISION : période de renouvellement des clés].")}),
            C("KY03", "Certificates must be inventoried with their owner and expiry date and renewed before they expire.",
              "Les certificats doivent être inventoriés avec leur responsable et leur date d’expiration et renouvelés avant leur échéance."),
        ]),
    ],
    evidence=[C("EV01", "Evidence includes encryption-status reports for endpoints, TLS configuration scans of internet-facing services, and the key and certificate inventory.",
                "Les preuves comprennent les rapports d’état du chiffrement des terminaux, les analyses de configuration TLS des services exposés à Internet et l’inventaire des clés et certificats.", mod="info")],
)

STD_LOG = standard_frame(
    purpose=[C("P01", "This standard specifies which events {org} systems must log, how long logs are kept, and how they are protected and reviewed.",
               "La présente norme précise les événements que les systèmes de {org} doivent journaliser, la durée de conservation des journaux et la façon de les protéger et de les revoir.", mod="info")],
    applicability=[C("AP01", "It applies to critical systems, identity providers, network security devices, cloud control planes and systems holding information classified Confidential or above.",
                     "Elle s’applique aux systèmes critiques, aux fournisseurs d’identité, aux dispositifs de sécurité réseau, aux consoles de gestion infonuagiques et aux systèmes contenant de l’information classifiée Confidentiel ou plus.", mod="info")],
    requirements=[
        S("SEC-REQ-SOURCES", "Log sources and events", "Sources et événements journalisés", [
            C("LS01", "Minimum log sources and events", "Sources et événements minimaux", table=TBL(
                ["Source", "Events to record"], ["Source", "Événements à consigner"],
                [["Identity provider and directory", "Sign-ins (success and failure), MFA events, account and group changes, privilege grants"],
                 ["Cloud and SaaS administration consoles", "Administrative actions, configuration and permission changes, API key creation"],
                 ["Servers and critical applications", "Authentication, privileged commands, access to Confidential data, security setting changes, errors"],
                 ["Endpoint protection", "Detections, quarantines, tampering attempts"],
                 ["Firewalls, VPN and remote access", "Allowed and denied connections at the perimeter, remote-access sessions"],
                 ["Backup systems", "Job results, deletions, retention changes"]],
                [["Fournisseur d’identité et annuaire", "Connexions (réussies et échouées), événements d’AMF, modifications de comptes et de groupes, octrois de privilèges"],
                 ["Consoles d’administration infonuagiques et SaaS", "Actions administratives, modifications de configuration et de permissions, création de clés d’API"],
                 ["Serveurs et applications critiques", "Authentification, commandes privilégiées, accès aux données confidentielles, modifications des paramètres de sécurité, erreurs"],
                 ["Protection des terminaux", "Détections, mises en quarantaine, tentatives d’altération"],
                 ["Pare-feu, RPV et accès à distance", "Connexions permises et refusées en périphérie, sessions d’accès à distance"],
                 ["Systèmes de sauvegarde", "Résultats des tâches, suppressions, modifications de conservation"]]),
              refs=["ISO 27002:2022 8.15", "CIS v8.1 8"]),
            C("LS02", "Every entry must include a timestamp synchronized to a common time source, the user or system identity, the source address where applicable, the action and its result.",
              "Chaque entrée doit inclure un horodatage synchronisé sur une source de temps commune, l’identité de l’utilisateur ou du système, l’adresse source s’il y a lieu, l’action et son résultat.",
              refs=["ISO 27002:2022 8.17"]),
            C("LS03", "Logs must not record passwords, secrets or full payment-card numbers; personal information in logs is limited to what investigations need.",
              "Les journaux ne doivent pas consigner de mots de passe, de secrets ni de numéros complets de cartes de paiement; les renseignements personnels qu’ils contiennent sont limités à ce qui est nécessaire aux enquêtes.",
              mod="must not", legal=True),
        ]),
        S("SEC-REQ-KEEP", "Retention, protection and review", "Conservation, protection et revue", [
            C("LK01", "Security logs are retained for {p:DEC-LOG-RETENTION}, unless a longer period is required by law or contract.",
              "Les journaux de sécurité sont conservés pendant {p:DEC-LOG-RETENTION}, sauf si la loi ou un contrat exige une période plus longue.",
              src="decision", inputs=["DEC-LOG-RETENTION"], legal=True),
            C("LK02", "Logs must be forwarded to a central store that system administrators cannot alter or delete; access to logs is limited to roles approved by {sec} and is itself logged.",
              "Les journaux doivent être acheminés vers un dépôt central que les administrateurs des systèmes ne peuvent ni modifier ni supprimer; l’accès aux journaux est limité aux rôles approuvés par {sec} et est lui-même journalisé.",
              refs=["ISO 27002:2022 8.15"]),
            C("LK03", by="DEC-LOG-REVIEW", src="decision", variants={
                "alerts_daily": V("Automated alerts are triaged every working day, and a broader review of security logs is performed weekly.", "Les alertes automatisées sont triées chaque jour ouvrable, et une revue plus large des journaux de sécurité est faite chaque semaine."),
                "weekly": V("Security logs are reviewed manually every week; reviews and findings are recorded.", "Les journaux de sécurité sont revus manuellement chaque semaine; les revues et constats sont consignés."),
                "mdr": V("Security logs are monitored continuously by the managed detection and response provider, which escalates alerts according to the incident management policy.",
                         "Les journaux de sécurité sont surveillés en continu par le fournisseur de détection et de réponse gérées, qui fait remonter les alertes conformément à la politique de gestion des incidents."),
                "_none": V("Security logs are reviewed [DECISION: log review method and frequency].", "Les journaux de sécurité sont revus [DÉCISION : méthode et fréquence de revue des journaux].")},
              refs=["ISO 27002:2022 8.16", "NIST CSF 2.0 DE.CM"]),
        ]),
    ],
    evidence=[C("EV01", "Evidence includes the list of connected log sources with their last-received time, retention settings and records of log reviews.",
                "Les preuves comprennent la liste des sources de journaux raccordées avec l’heure de la dernière réception, les paramètres de conservation et les traces des revues de journaux.", mod="info")],
)

# ================================================================== PROCEDURES
RACI_COLS = (["Activity", "Responsible", "Accountable", "Consulted", "Informed"], ["Activité", "Réalise", "Approuve", "Consulté", "Informé"])

PRC_IR = procedure_frame(
    purpose=[C("PU01", "This procedure describes how {org} handles a suspected or confirmed security incident, from the first report to the post-incident review.",
               "La présente procédure décrit comment {org} traite un incident de sécurité soupçonné ou confirmé, du premier signalement à la revue post-incident.", mod="info")],
    trigger=[C("TG01", "It starts when anyone reports a suspected incident, when a security alert is raised, or when a supplier notifies an incident affecting {org}.",
               "Elle s’applique dès qu’une personne signale un incident soupçonné, qu’une alerte de sécurité est émise ou qu’un fournisseur signale un incident touchant {org}.", mod="info")],
    inputs=[
        C("IN01", "Current contact list for the incident team, executives, legal counsel, insurer and key suppliers: [VALUE: location of the incident contact list].",
          "Liste à jour des coordonnées de l’équipe d’intervention, des dirigeants, du conseiller juridique, de l’assureur et des fournisseurs clés : [VALEUR : emplacement de la liste des contacts d’incident]."),
        C("IN02", "Access to the incident register and decision log, and an out-of-band communication channel that does not depend on possibly compromised systems.",
          "Accès au registre des incidents et au journal des décisions, ainsi qu’un canal de communication de rechange qui ne dépend pas de systèmes possiblement compromis."),
    ],
    roles_table=[C("RA01", "Responsibility matrix", "Matrice des responsabilités", mod="info", table=TBL(
        RACI_COLS[0], RACI_COLS[1],
        [["Report and register the incident", "Reporter; {sec}", "{Sec}", "—", "Manager of the reporter"],
         ["Triage and severity", "{Sec}", "{Sec}", "System owner", "Designated executive (S1–S2)"],
         ["Containment", "IT operations or service provider", "{Sec}", "System owner", "Designated executive"],
         ["Notification assessment", "{Privacy}; legal counsel", "Designated executive", "{Sec}", "{Committee}"],
         ["External communication", "Communications", "Designated executive", "Legal counsel; {sec}", "Staff"],
         ["Post-incident review", "{Sec}", "{Committee}", "Everyone involved", "Management"]],
        [["Signaler et consigner l’incident", "Déclarant; {sec}", "{Sec}", "—", "Gestionnaire du déclarant"],
         ["Triage et gravité", "{Sec}", "{Sec}", "Responsable du système", "Dirigeant désigné (S1–S2)"],
         ["Confinement", "Exploitation des TI ou fournisseur de services", "{Sec}", "Responsable du système", "Dirigeant désigné"],
         ["Évaluation des notifications", "{Privacy}; conseiller juridique", "Dirigeant désigné", "{Sec}", "{Committee}"],
         ["Communication externe", "Communications", "Dirigeant désigné", "Conseiller juridique; {sec}", "Personnel"],
         ["Revue post-incident", "{Sec}", "{Committee}", "Toutes les personnes impliquées", "Direction"]]))],
    steps_sections=[
        S("SEC-STEPS", "Steps", "Étapes", [
            C("ST01", "Receive the report through the published channel, open an entry in the incident register (time, reporter, systems, first observations) and acknowledge the reporter.",
              "Recevoir le signalement par le canal publié, ouvrir une entrée au registre des incidents (heure, déclarant, systèmes, premières observations) et en accuser réception au déclarant."),
            C("ST02", "Triage: confirm whether it is an incident and assign a severity using the table below.", "Triage : confirmer s’il s’agit d’un incident et attribuer une gravité selon le tableau ci-dessous.",
              table=TBL(["Severity", "Typical criteria", "Start of response"], ["Gravité", "Critères types", "Début de l’intervention"],
                        [["S1 — Critical", "A critical service is down; confirmed theft or exposure of personal or confidential information; ransomware", "[DECISION: S1 response time]"],
                         ["S2 — High", "Compromised privileged account; malware spreading; supplier incident affecting critical data", "[DECISION: S2 response time]"],
                         ["S3 — Medium", "Single compromised user account or device, contained", "[DECISION: S3 response time]"],
                         ["S4 — Low", "Policy violation or blocked attempt without impact", "Next working day"]],
                        [["S1 — Critique", "Un service essentiel est interrompu; vol ou exposition confirmés de renseignements personnels ou confidentiels; rançongiciel", "[DÉCISION : délai d’intervention S1]"],
                         ["S2 — Élevée", "Compte privilégié compromis; logiciel malveillant qui se propage; incident chez un fournisseur touchant des données critiques", "[DÉCISION : délai d’intervention S2]"],
                         ["S3 — Moyenne", "Un seul compte ou appareil compromis, maîtrisé", "[DÉCISION : délai d’intervention S3]"],
                         ["S4 — Faible", "Manquement à une politique ou tentative bloquée sans impact", "Jour ouvrable suivant"]])),
            C("ST03", "For S1 and S2, inform the designated executive immediately and convene the incident team; the executive decides whether to activate crisis management and business continuity plans.",
              "Pour S1 et S2, informer immédiatement le dirigeant désigné et réunir l’équipe d’intervention; le dirigeant décide d’activer ou non la gestion de crise et les plans de continuité."),
            C("ST04", "Contain: isolate affected devices, disable compromised accounts, block malicious addresses, within the authority set by the incident management policy. Record every action and its time in the decision log.",
              "Confiner : isoler les appareils touchés, désactiver les comptes compromis, bloquer les adresses malveillantes, dans les limites de l’autorité prévue par la politique de gestion des incidents. Consigner chaque action et son heure au journal des décisions."),
            C("ST05", "Preserve evidence before wiping or rebuilding: system images or snapshots, relevant logs and messages, with a record of who collected them and when.",
              "Préserver la preuve avant d’effacer ou de reconstruire : images ou instantanés des systèmes, journaux et messages pertinents, en consignant qui les a recueillis et quand.",
              refs=["ISO 27002:2022 5.28"]),
            C("ST06", "Assess notification duties without delay: {privacy} and legal counsel determine whether regulators, affected individuals, clients, the insurer or law enforcement must be notified, and by when.",
              "Évaluer sans délai les obligations de notification : {privacy} et le conseiller juridique déterminent si les régulateurs, les personnes concernées, les clients, l’assureur ou les forces de l’ordre doivent être avisés, et dans quel délai.",
              legal=True),
            C("ST07", "Eradicate the cause, restore from known-good backups, verify integrity and monitor closely before returning systems to normal operation.",
              "Éliminer la cause, restaurer à partir de sauvegardes saines, vérifier l’intégrité et surveiller étroitement avant le retour à l’exploitation normale."),
            C("ST08", by="DEC-PIR-DAYS", src="decision", variants={
                "5": V("Close the incident in the register and hold a post-incident review within 5 working days for S1–S2 incidents; assign owners and dates to each improvement.",
                       "Clore l’incident au registre et tenir une revue post-incident dans les 5 jours ouvrables pour les incidents S1–S2; attribuer un responsable et une date à chaque amélioration."),
                "10": V("Close the incident in the register and hold a post-incident review within 10 working days for S1–S2 incidents; assign owners and dates to each improvement.",
                        "Clore l’incident au registre et tenir une revue post-incident dans les 10 jours ouvrables pour les incidents S1–S2; attribuer un responsable et une date à chaque amélioration."),
                "_none": V("Close the incident and hold a post-incident review within [DECISION: post-incident review delay].",
                           "Clore l’incident et tenir une revue post-incident dans un délai de [DÉCISION : délai de la revue post-incident].")},
              refs=["ISO 27002:2022 5.27"]),
        ]),
    ],
    records=[C("RC01", "Records kept: incident register entry, decision log, evidence inventory, notifications made and their dates, post-incident report and action plan.",
               "Registres tenus : entrée au registre des incidents, journal des décisions, inventaire des preuves, notifications effectuées et leurs dates, rapport post-incident et plan d’action.", mod="info")],
    testing=[C("TS01", "This procedure is exercised {p:DEC-IR-EXERCISE} and updated after each exercise and each S1–S2 incident.",
               "La présente procédure est mise à l’essai {p:DEC-IR-EXERCISE} et mise à jour après chaque exercice et chaque incident S1–S2.",
               src="decision", inputs=["DEC-IR-EXERCISE"])],
)

PRC_JML = procedure_frame(
    purpose=[C("PU01", "This procedure describes how access is granted, changed and removed when people join, move within or leave {org}, and how access is periodically reviewed.",
               "La présente procédure décrit comment les accès sont accordés, modifiés et retirés lorsque des personnes arrivent chez {org}, y changent de fonctions ou la quittent, et comment les accès sont revus périodiquement.", mod="info")],
    trigger=[C("TG01", "It starts with a hiring, role-change or departure notice from human resources or a manager, a contractor engagement, or the scheduled access review.",
               "Elle s’applique sur réception d’un avis d’embauche, de changement de fonctions ou de départ des ressources humaines ou d’un gestionnaire, d’un engagement de contractuel, ou lors de la revue d’accès planifiée.", mod="info")],
    inputs=[C("IN01", "Inputs: the person’s identity and role, start or end date, manager, and the role-based access profile approved by system owners.",
              "Intrants : l’identité et le rôle de la personne, la date de début ou de fin, le gestionnaire et le profil d’accès par rôle approuvé par les responsables des systèmes.", mod="info")],
    roles_table=[C("RA01", "Responsibility matrix", "Matrice des responsabilités", mod="info", table=TBL(
        RACI_COLS[0], RACI_COLS[1],
        [["Notify joiner, mover or leaver", "Human resources; manager", "Manager", "—", "Access administration"],
         ["Approve access", "System owner", "System owner", "{Sec}", "Manager"],
         ["Create, change or disable accounts", "Access administration", "IT lead", "—", "Manager"],
         ["Recertify access", "System owner", "System owner", "Manager", "{Sec}"]],
        [["Aviser d’une arrivée, d’un mouvement ou d’un départ", "Ressources humaines; gestionnaire", "Gestionnaire", "—", "Administration des accès"],
         ["Approuver l’accès", "Responsable du système", "Responsable du système", "{Sec}", "Gestionnaire"],
         ["Créer, modifier ou désactiver des comptes", "Administration des accès", "Responsable des TI", "—", "Gestionnaire"],
         ["Recertifier les accès", "Responsable du système", "Responsable du système", "Gestionnaire", "{Sec}"]]))],
    steps_sections=[
        S("SEC-STEPS-JOIN", "Joiners", "Arrivées", [
            C("JN01", "Human resources or the sponsoring manager submits the request at least [VALUE: number of working days] before the start date.",
              "Les ressources humaines ou le gestionnaire parrain soumettent la demande au moins [VALEUR : nombre de jours ouvrables] avant la date d’entrée en fonction."),
            C("JN02", "Access administration creates a unique account with the role-based profile; any access beyond the profile requires the system owner’s approval.",
              "L’administration des accès crée un compte unique avec le profil du rôle; tout accès qui excède le profil exige l’approbation du responsable du système."),
            C("JN03", "The person enrols in multi-factor authentication and acknowledges the acceptable use rules before receiving access to information.",
              "La personne s’inscrit à l’authentification multifacteur et prend connaissance des règles d’utilisation acceptable avant d’accéder à l’information."),
        ]),
        S("SEC-STEPS-MOVE", "Movers", "Mouvements", [
            C("MV01", "On a role change, the manager confirms which existing access is still needed; access no longer needed is removed within [VALUE: number of working days] of the change.",
              "Lors d’un changement de fonctions, le gestionnaire confirme les accès qui demeurent nécessaires; ceux qui ne le sont plus sont retirés dans un délai de [VALEUR : nombre de jours ouvrables] après le changement."),
            C("MV02", "New access follows the joiner approval steps.", "Les nouveaux accès suivent les étapes d’approbation applicables aux arrivées."),
        ]),
        S("SEC-STEPS-LEAVE", "Leavers", "Départs", [
            C("LV01", by="DEC-IAM-LEAVER", src="decision", variants={
                "same_day": V("Access administration disables all accounts and revokes tokens and sessions no later than the end of the last working day — immediately for an involuntary departure.",
                              "L’administration des accès désactive tous les comptes et révoque jetons et sessions au plus tard à la fin du dernier jour de travail — immédiatement en cas de départ non volontaire."),
                "24h": V("Access administration disables all accounts and revokes tokens and sessions within 24 hours — immediately for an involuntary departure.",
                         "L’administration des accès désactive tous les comptes et révoque jetons et sessions dans les 24 heures — immédiatement en cas de départ non volontaire."),
                "72h": V("Access administration disables all accounts and revokes tokens and sessions within 72 hours — immediately for an involuntary departure.",
                         "L’administration des accès désactive tous les comptes et révoque jetons et sessions dans les 72 heures — immédiatement en cas de départ non volontaire."),
                "_none": V("Access administration disables all accounts within [DECISION: deadline to disable access after departure].",
                           "L’administration des accès désactive tous les comptes dans un délai de [DÉCISION : délai de désactivation des accès après un départ].")}),
            C("LV02", "Shared secrets the person knew are changed, devices and badges are recovered, and mailbox and file ownership is transferred to the manager.",
              "Les secrets partagés que la personne connaissait sont changés, les appareils et badges sont récupérés, et la propriété de la boîte de courriel et des fichiers est transférée au gestionnaire."),
        ]),
        S("SEC-STEPS-REVIEW", "Periodic review", "Revue périodique", [
            C("RV10", "Owners recertify access at the frequency set in the identity and access management policy ({p:DEC-IAM-REVIEW}); access not confirmed within [VALUE: number of days] of the review request is removed.",
              "Les responsables recertifient les accès à la fréquence fixée dans la politique de gestion des identités et des accès ({p:DEC-IAM-REVIEW}); les accès non confirmés dans les [VALEUR : nombre de jours] suivant la demande de revue sont retirés.",
              src="decision", inputs=["DEC-IAM-REVIEW"]),
        ]),
    ],
    records=[C("RC01", "Records kept: requests and approvals, account creation and removal dates, review results and the removals they triggered.",
               "Registres tenus : demandes et approbations, dates de création et de retrait des comptes, résultats des revues et retraits qui en découlent.", mod="info")],
    testing=[C("TS01", "{Sec} samples leavers at least quarterly to verify that access was removed on time and reports exceptions.",
               "{Sec} vérifie par échantillonnage, au moins chaque trimestre, que les accès des personnes parties ont été retirés à temps et signale les écarts.")],
)

PRC_EXC = procedure_frame(
    purpose=[C("PU01", "This procedure describes how a person requests an exception to a security requirement and how it is assessed, approved, recorded, renewed and closed.",
               "La présente procédure décrit comment demander une dérogation à une exigence de sécurité et comment elle est évaluée, approuvée, consignée, renouvelée et close.", mod="info")],
    trigger=[C("TG01", "It applies whenever a requirement of a security policy or standard cannot be met, temporarily or permanently.",
               "Elle s’applique chaque fois qu’une exigence d’une politique ou d’une norme de sécurité ne peut être respectée, temporairement ou de façon permanente.", mod="info")],
    inputs=[C("IN01", "The request states: the requirement concerned, the systems or people affected, the reason, the proposed duration, compensating controls, the residual risk and a plan to comply.",
              "La demande précise : l’exigence visée, les systèmes ou personnes touchés, la raison, la durée proposée, les mesures compensatoires, le risque résiduel et un plan pour se conformer.")],
    roles_table=[C("RA01", "Responsibility matrix", "Matrice des responsabilités", mod="info", table=TBL(
        RACI_COLS[0], RACI_COLS[1],
        [["Submit the request", "Requester", "Requester’s manager", "System owner", "—"],
         ["Assess the risk", "{Sec}", "{Sec}", "System owner", "—"],
         ["Approve or refuse", "Approver per the policy", "Risk owner", "{Sec}", "Requester"],
         ["Record and monitor", "{Sec}", "{Sec}", "—", "{Committee}"]],
        [["Soumettre la demande", "Demandeur", "Gestionnaire du demandeur", "Responsable du système", "—"],
         ["Évaluer le risque", "{Sec}", "{Sec}", "Responsable du système", "—"],
         ["Approuver ou refuser", "Approbateur selon la politique", "Responsable du risque", "{Sec}", "Demandeur"],
         ["Consigner et suivre", "{Sec}", "{Sec}", "—", "{Committee}"]]))],
    steps_sections=[S("SEC-STEPS", "Steps", "Étapes", [
        C("ST01", "The requester submits the request with the information above before departing from the requirement, except in an emergency, in which case the request is submitted within one working day.",
          "Le demandeur soumet la demande avec l’information ci-dessus avant de déroger à l’exigence, sauf en cas d’urgence, auquel cas la demande est soumise dans un délai d’un jour ouvrable."),
        C("ST02", "{Sec} assesses the residual risk and the compensating controls and gives a recommendation. A request that sets aside a legal, regulatory or contractual obligation is refused.",
          "{Sec} évalue le risque résiduel et les mesures compensatoires et formule une recommandation. Une demande qui écarte une obligation légale, réglementaire ou contractuelle est refusée."),
        C("ST03", by="DEC-EXC-APPROVER", src="decision", variants={
            "risk_owner": V("The accountable risk owner approves or refuses the exception in writing.", "Le responsable du risque approuve ou refuse la dérogation par écrit."),
            "exec": V("The executive committee approves or refuses the exception in writing.", "Le comité de direction approuve ou refuse la dérogation par écrit."),
            "tiered": V("The accountable risk owner decides on exceptions with moderate residual risk; {committee} decides on those with high residual risk.",
                        "Le responsable du risque statue sur les dérogations à risque résiduel modéré; {committee} statue sur celles à risque résiduel élevé."),
            "_none": V("[DECISION: exception approval authority] approves or refuses the exception in writing.", "[DÉCISION : autorité d’approbation des dérogations] approuve ou refuse la dérogation par écrit.")}),
        C("ST04", "{Sec} records the decision in the exception register with its expiry date, which may not exceed {p:DEC-EXC-MAX}.",
          "{Sec} consigne la décision au registre des dérogations avec sa date d’échéance, qui ne peut excéder {p:DEC-EXC-MAX}.",
          src="decision", inputs=["DEC-EXC-MAX"]),
        C("ST05", "The exception owner is reminded {p:DEC-EXC-NOTICE}; the exception is then closed, renewed after a new assessment, or escalated. An expired exception no longer covers the departure.",
          "Le responsable de la dérogation reçoit un rappel {p:DEC-EXC-NOTICE}; la dérogation est alors close, renouvelée après une nouvelle évaluation, ou portée au niveau supérieur. Une dérogation échue ne couvre plus l’écart.",
          src="decision", inputs=["DEC-EXC-NOTICE"]),
    ])],
    records=[C("RC01", "Records kept: request, risk assessment, decision with approver identity and date, renewals and closure, in the exception register.",
               "Registres tenus : demande, évaluation du risque, décision avec l’identité de l’approbateur et la date, renouvellements et clôture, au registre des dérogations.", mod="info")],
    testing=[C("TS01", "{Sec} reports the exception register to {committee} at least quarterly, including the number of active and expired exceptions.",
               "{Sec} présente le registre des dérogations à {committee} au moins une fois par trimestre, y compris le nombre de dérogations actives et échues.")],
)

PRC_RESTORE = procedure_frame(
    purpose=[C("PU01", "This procedure describes how restoration from backup is tested so that {org} knows, with evidence, that it can recover its critical services.",
               "La présente procédure décrit comment la restauration à partir des sauvegardes est testée afin que {org} sache, preuves à l’appui, qu’elle peut rétablir ses services essentiels.", mod="info")],
    trigger=[C("TG01", "It applies {p:DEC-BKP-TEST}, after a significant change to a critical system or to the backup solution, and after any failed restoration.",
               "Elle s’applique {p:DEC-BKP-TEST}, après un changement important à un système critique ou à la solution de sauvegarde, et après toute restauration échouée.",
               src="decision", inputs=["DEC-BKP-TEST"])],
    inputs=[C("IN01", "Inputs: the list of critical systems with their recovery objectives, access to an isolated restoration environment, and the documented recovery steps for each system.",
              "Intrants : la liste des systèmes critiques avec leurs objectifs de rétablissement, l’accès à un environnement de restauration isolé et les étapes de rétablissement documentées de chaque système.", mod="info")],
    roles_table=[C("RA01", "Responsibility matrix", "Matrice des responsabilités", mod="info", table=TBL(
        RACI_COLS[0], RACI_COLS[1],
        [["Plan the test", "IT operations", "IT lead", "System owner", "{Sec}"],
         ["Perform the restoration", "IT operations or service provider", "IT lead", "—", "—"],
         ["Validate the restored data", "System owner", "System owner", "IT operations", "{Sec}"],
         ["Track corrective actions", "IT lead", "IT lead", "{Sec}", "{Committee}"]],
        [["Planifier le test", "Exploitation des TI", "Responsable des TI", "Responsable du système", "{Sec}"],
         ["Effectuer la restauration", "Exploitation des TI ou fournisseur de services", "Responsable des TI", "—", "—"],
         ["Valider les données restaurées", "Responsable du système", "Responsable du système", "Exploitation des TI", "{Sec}"],
         ["Suivre les mesures correctives", "Responsable des TI", "Responsable des TI", "{Sec}", "{Committee}"]]))],
    steps_sections=[S("SEC-STEPS", "Steps", "Étapes", [
        C("ST01", "Select the systems to test so that each critical system is tested at least once a year, including at least one restoration from the offline or immutable copy where one exists.",
          "Choisir les systèmes à tester de sorte que chaque système critique soit testé au moins une fois par année, y compris au moins une restauration à partir de la copie hors ligne ou immuable s’il en existe une."),
        C("ST02", "Restore to an isolated environment that cannot affect production, and record the start time.",
          "Restaurer dans un environnement isolé qui ne peut toucher la production et noter l’heure de début."),
        C("ST03", "Have the system owner verify the completeness and integrity of the restored data and that the application works.",
          "Faire vérifier par le responsable du système l’intégralité et l’intégrité des données restaurées et le fonctionnement de l’application."),
        C("ST04", "Compare the elapsed time and the age of the restored data with the system’s recovery time and recovery point objectives.",
          "Comparer le temps écoulé et l’âge des données restaurées aux objectifs de délai et de point de rétablissement du système."),
        C("ST05", "Record the result; a failed test or a missed objective opens a corrective action with an owner and a date, and is reported to {sec}.",
          "Consigner le résultat; un test échoué ou un objectif non atteint donne lieu à une mesure corrective avec un responsable et une date, et est signalé à {sec}."),
        C("ST06", "Securely delete the restored copy after the test.", "Supprimer de façon sécuritaire la copie restaurée après le test."),
    ])],
    records=[C("RC01", "Records kept: test plan, restoration logs, owner validation, times measured against objectives, corrective actions.",
               "Registres tenus : plan de test, journaux de restauration, validation du responsable, temps mesurés par rapport aux objectifs, mesures correctives.", mod="info")],
    testing=[C("TS01", "IT operations updates the documented recovery steps after every test that reveals a gap.",
               "L’exploitation des TI met à jour les étapes de rétablissement documentées après chaque test qui révèle une lacune.")],
)
